// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ProxyGroup) predicate.ProxyGroup {
	return predicate.ProxyGroup(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ProxyGroup) predicate.ProxyGroup {
	return predicate.ProxyGroup(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ProxyGroup) predicate.ProxyGroup {
	return predicate.ProxyGroup(sql.NotPredicates(p))
}
